#!/usr/bin/env python3
"""Run a full offline reactor build and summarise compile failures per module.

Usage: python3 agent_plans/compile_gate.py [logfile]
Writes /tmp/compile_report.json and prints a summary.
"""
import json, re, subprocess, sys, os

LOG = sys.argv[1] if len(sys.argv) > 1 else '/tmp/mvn-gate.log'

CMD = ['flock', '/tmp/hadoop-mvn.lock',
       'mvn', '-o', '-B', '-DskipTests', '-fae',
       '-Dmaven.javadoc.skip=true', '-Denforcer.skip=true', '-Dcheckstyle.skip=true',
       '-Dspotbugs.skip=true', '-Dpmd.skip=true', '-Drat.skip=true', 'install']


def run():
    with open(LOG, 'w') as fh:
        subprocess.run(CMD, cwd='/workspace', stdout=fh, stderr=subprocess.STDOUT)


def parse():
    text = open(LOG, errors='replace').read().splitlines()
    modules = {}
    cur = None
    errors = []
    for line in text:
        m = re.match(r'\[ERROR\] Failed to execute goal .* on project ([\w.-]+): (.*)', line)
        if m:
            cur = m.group(1)

